     "s": "Élise sentit son cœur, celui de Sophia, battre jusque dans sa gorge. Elle aurait dû partir, faire demi-tour, rentrer, écrire tout cela dans le carnet et ne plus jamais sortir la nuit. Elle s'approcha."
